        return Iterator(utf8.Iterator).init(.init(bytes));
}

pub fn testIteratorNextcodepointPeekcodepoint() !void {
        const str: []const u8 = "👩🏽‍🚀🇨🇭";
        var it = Iterator(utf8.Iterator).init(.init(str));
        _ = &it;
        _ = try std.testing.expect((it.i == 0));
        var result = it.peekCodePoint();
        _ = &result;
        _ = try std.testing.expect((it.i == 0));
        _ = try std.testing.expect((result.?.code_point == 128105));
        _ = try std.testing.expect((result.?.is_break == false));
        result = it.nextCodePoint();
        _ = try std.testing.expect((it.i == 4));
        _ = try std.testing.expect((result.?.code_point == 128105));
        _ = try std.testing.expect((result.?.is_break == false));
        result = it.nextCodePoint();
        _ = try std.testing.expect((result.?.code_point == 127997));
        _ = try std.testing.expect((result.?.is_break == false));
        result = it.nextCodePoint();
        _ = try std.testing.expect((result.?.code_point == 8205));
        _ = try std.testing.expect((result.?.is_break == false));
        result = it.peekCodePoint();
        _ = try std.testing.expect((result.?.code_point == 128640));
        _ = try std.testing.expect((result.?.is_break == true));
        result = it.nextCodePoint();
        _ = try std.testing.expect((it.i == 15));
        _ = try std.testing.expect((result.?.code_point == 128640));
        _ = try std.testing.expect((result.?.is_break == true));
        _ = try std.testing.expect(std.mem.eql(u8, str[0..it.i], "👩🏽‍🚀"));
        result = it.nextCodePoint();
        _ = try std.testing.expect((result.?.code_point == 127464));
        _ = try std.testing.expect((result.?.is_break == false));
        result = it.nextCodePoint();
        _ = try std.testing.expect((it.i == str.len));
        _ = try std.testing.expect((result.?.code_point == 127469));
        _ = try std.testing.expect((result.?.is_break == true));
        _ = try std.testing.expect((it.peekCodePoint() == null));
        _ = try std.testing.expect((it.nextCodePoint() == null));
        _ = try std.testing.expect((it.nextCodePoint() == null));
}

pub fn testUtf8iteratorNextgraphemePeekgrapheme() !void {
        const str: []const u8 = "👩🏽‍🚀🇨🇭👨🏻‍🍼";
        var it = utf8Iterator(str);
        _ = &it;
        _ = try std.testing.expect((it.i == 0));
        var result = it.peekGrapheme();
        _ = &result;
        _ = try std.testing.expect((result.?.start == 0));
        _ = try std.testing.expect((result.?.end == 15));
        _ = try std.testing.expect((it.i == 0));
        result = it.nextGrapheme();
        _ = try std.testing.expect((result.?.start == 0));
        _ = try std.testing.expect((result.?.end == 15));
        _ = try std.testing.expect((it.i == 15));
        _ = try std.testing.expect(std.mem.eql(u8, str[result.?.start..result.?.end], "👩🏽‍🚀"));
        result = it.nextGrapheme();
        _ = try std.testing.expect((result.?.start == 15));
        _ = try std.testing.expect((result.?.end == 23));
        _ = try std.testing.expect((it.i == 23));
        _ = try std.testing.expect(std.mem.eql(u8, str[result.?.start..result.?.end], "🇨🇭"));
        result = it.peekGrapheme();
        _ = try std.testing.expect((result.?.start == 23));
        _ = try std.testing.expect((result.?.end == str.len));
        _ = try std.testing.expect(std.mem.eql(u8, str[result.?.start..result.?.end], "👨🏻‍🍼"));
        result = it.nextGrapheme();
        _ = try std.testing.expect((result.?.start == 23));
        _ = try std.testing.expect((result.?.end == str.len));
        _ = try std.testing.expect((it.i == str.len));
        _ = try std.testing.expect((it.peekGrapheme() == null));
        _ = try std.testing.expect((it.nextGrapheme() == null));
        _ = try std.testing.expect((it.nextGrapheme() == null));
}

pub fn computeGraphemeBreak(gb1: types.GraphemeBreak, gb2: types.GraphemeBreak, state: *BreakState) bool {
        switch (state.*) {
.regional_indicator => {
if (((gb1 != .regional_indicator) or (gb2 != .regional_indicator))) {
            state.* = .default;
        }
},
.extended_pictographic => {
switch (gb1) {
.indic_conjunct_break_extend, .indic_conjunct_break_linker, .zwnj, .zwj, .extended_pictographic, .emoji_modifier_base, .emoji_modifier => {

},
else => {
state.* = .default;
},
}
        switch (gb2) {
.indic_conjunct_break_extend, .indic_conjunct_break_linker, .zwnj, .zwj, .extended_pictographic, .emoji_modifier_base, .emoji_modifier => {

},
else => {
state.* = .default;
},
}
},
.indic_conjunct_break_consonant, .indic_conjunct_break_linker => {
switch (gb1) {
.indic_conjunct_break_consonant, .indic_conjunct_break_linker, .indic_conjunct_break_extend, .zwj => {

},
else => {
state.* = .default;
},
}
        switch (gb2) {
.indic_conjunct_break_consonant, .indic_conjunct_break_linker, .indic_conjunct_break_extend, .zwj => {

},
else => {
state.* = .default;
},
}
},
.default => {

},
}
        if (((gb1 == .cr) and (gb2 == .lf))) {
            return false;
        }
        if ((((gb1 == .control) or (gb1 == .cr)) or (gb1 == .lf))) {
            return true;
        }
        if ((((gb2 == .control) or (gb2 == .cr)) or (gb2 == .lf))) {
            return true;
        }
        if ((gb1 == .l)) {
            if (((((gb2 == .l) or (gb2 == .v)) or (gb2 == .lv)) or (gb2 == .lvt))) {
                return false;
            }
        }
        if (((gb1 == .lv) or (gb1 == .v))) {
            if (((gb2 == .v) or (gb2 == .t))) {
                return false;
            }
        }
        if (((gb1 == .lvt) or (gb1 == .t))) {
            if ((gb2 == .t)) {
                return false;
            }
        }
        if ((gb2 == .spacing_mark)) {
            return false;
        }
        if ((gb1 == .prepend)) {
            return false;
        }
        if ((gb1 == .indic_conjunct_break_consonant)) {
            if (isIndicConjunctBreakExtend(gb2)) {
                state.* = .indic_conjunct_break_consonant;
                return false;
            } else {
                if ((gb2 == .indic_conjunct_break_linker)) {
                    state.* = .indic_conjunct_break_linker;
                    return false;
                }
            }
        } else {
            if ((state.* == .indic_conjunct_break_consonant)) {
                if ((gb2 == .indic_conjunct_break_linker)) {
                    state.* = .indic_conjunct_break_linker;
                    return false;
                } else {
                    if (isIndicConjunctBreakExtend(gb2)) {
                        return false;
                    } else {
                        state.* = .default;
                    }
                }
            } else {
                if ((state.* == .indic_conjunct_break_linker)) {
                    if (((gb2 == .indic_conjunct_break_linker) or isIndicConjunctBreakExtend(gb2))) {
                        return false;
                    } else {
                        if ((gb2 == .indic_conjunct_break_consonant)) {
                            state.* = .default;
                            return false;
                        } else {
                            state.* = .default;
                        }
                    }
                }
            }
        }
        if (isExtendedPictographic(gb1)) {
            if ((isExtend(gb2) or (gb2 == .zwj))) {
                state.* = .extended_pictographic;
                return false;
            }
            if (((gb1 == .emoji_modifier_base) and (gb2 == .emoji_modifier))) {
                state.* = .extended_pictographic;
                return false;
            }
        } else {
            if ((state.* == .extended_pictographic)) {
                if (((isExtend(gb1) or (gb1 == .emoji_modifier)) and (isExtend(gb2) or (gb2 == .zwj)))) {
                    return false;
                } else {
                    if (((gb1 == .zwj) and isExtendedPictographic(gb2))) {
                        state.* = .default;
                        return false;
                    } else {
                        state.* = .default;
                    }
                }
            }
        }
        if (((gb1 == .regional_indicator) and (gb2 == .regional_indicator))) {
            if ((state.* == .default)) {
                state.* = .regional_indicator;
                return false;
            } else {
                state.* = .default;
                return true;
            }
        }
        if ((isExtend(gb2) or (gb2 == .zwj))) {
            return false;
        }
        return true;
}

pub fn isIndicConjunctBreakExtend(gb: types.GraphemeBreak) bool {
        return ((gb == .indic_conjunct_break_extend) or (gb == .zwj));
}

pub fn isExtend(gb: types.GraphemeBreak) bool {
        return (((gb == .zwnj) or (gb == .indic_conjunct_break_extend)) or (gb == .indic_conjunct_break_linker));
}

pub fn isExtendedPictographic(gb: types.GraphemeBreak) bool {
        return ((gb == .extended_pictographic) or (gb == .emoji_modifier_base));
}

pub fn testGraphemeBreak(getActualIsBreak: *const fn (u21, u21, *BreakState) bool) !void {
        const trim = Ucd.trim;
        const parseCp = Ucd.parseCp;
        const allocator = std.testing.allocator;
        const file_path: []const u8 = "ucd/auxiliary/GraphemeBreakTest.txt";
        const file = try std.fs.cwd().openFile(file_path, .{});
        var _file_guard = CloseGuard(std.fs.File){ .val = file };
        _ = &_file_guard;
        var ___file_guard_moved = false; _ = &___file_guard_moved;
        defer if (!___file_guard_moved) { ___file_guard_moved = true; const __T = @TypeOf(_file_guard); if (@typeInfo(__T) == .optional) { if (_file_guard) |__cp_opt_v| { const __OptT = @TypeOf(__cp_opt_v); if (@typeInfo(__OptT) == .pointer and @typeInfo(__OptT).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__OptT).pointer), "is_const")) !@typeInfo(__OptT).pointer.is_const else !@typeInfo(__OptT).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__OptT).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { __cp_opt_v.__cp_deinit(); } } else if (@typeInfo(__OptT) == .@"struct" and @hasDecl(__OptT, "__cp_deinit")) { var _drop_val = __cp_opt_v; _drop_val.__cp_deinit(); } } } else if (@typeInfo(__T) == .pointer and @typeInfo(__T).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__T).pointer), "is_const")) !@typeInfo(__T).pointer.is_const else !@typeInfo(__T).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__T).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { _file_guard.__cp_deinit(); } } else if (@typeInfo(__T) == .@"struct" and @hasDecl(__T, "__cp_deinit")) { var _drop_val = _file_guard; _drop_val.__cp_deinit(); } };
        const content = try file.readToEndAlloc(allocator, ((1024 * 1024) * 10));
        var _content_guard = FreeGuard(@TypeOf(content)){ .alloc = allocator, .slice = content };
        _ = &_content_guard;
        var ___content_guard_moved = false; _ = &___content_guard_moved;
        defer if (!___content_guard_moved) { ___content_guard_moved = true; const __T = @TypeOf(_content_guard); if (@typeInfo(__T) == .optional) { if (_content_guard) |__cp_opt_v| { const __OptT = @TypeOf(__cp_opt_v); if (@typeInfo(__OptT) == .pointer and @typeInfo(__OptT).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__OptT).pointer), "is_const")) !@typeInfo(__OptT).pointer.is_const else !@typeInfo(__OptT).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__OptT).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { __cp_opt_v.__cp_deinit(); } } else if (@typeInfo(__OptT) == .@"struct" and @hasDecl(__OptT, "__cp_deinit")) { var _drop_val = __cp_opt_v; _drop_val.__cp_deinit(); } } } else if (@typeInfo(__T) == .pointer and @typeInfo(__T).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__T).pointer), "is_const")) !@typeInfo(__T).pointer.is_const else !@typeInfo(__T).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__T).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { _content_guard.__cp_deinit(); } } else if (@typeInfo(__T) == .@"struct" and @hasDecl(__T, "__cp_deinit")) { var _drop_val = _content_guard; _drop_val.__cp_deinit(); } };
        var lines = std.mem.splitScalar(u8, content, 10);
        _ = &lines;
        var success = true;
        _ = &success;
        var line_num: usize = 1;
        _ = &line_num;
        while (lines.next()) |line| : (line_num = (line_num + 1)) {
            const trimmed = trim(line);
            if ((trimmed.len == 0)) {
                continue;
            }
            var parts = std.mem.splitScalar(u8, trimmed, 32);
            _ = &parts;
            const start = (parts.next()).?;
            _ = try std.testing.expect(std.mem.eql(u8, start, "÷"));
            var state: BreakState = .default;
            _ = &state;
            var cp1 = try parseCp((parts.next()).?);
            _ = &cp1;
            var gb1 = getpkg.get(.grapheme_break, cp1);
            _ = &gb1;
            var expected_str = (parts.next()).?;
            _ = &expected_str;
            var cp2 = try parseCp((parts.next()).?);
            _ = &cp2;
            var gb2 = getpkg.get(.grapheme_break, cp2);
            _ = &gb2;
            var next_expected_str = (parts.next()).?;
            _ = &next_expected_str;
            while (true) {
                var expected_is_break = std.mem.eql(u8, expected_str, "÷");
                _ = &expected_is_break;
                const actual_is_break = getActualIsBreak(cp1, cp2, (&state));
                _ = try std.testing.expect((expected_is_break or std.mem.eql(u8, expected_str, "×")));
                if (((gb2 == .emoji_modifier) and (gb1 != .emoji_modifier_base))) {
                    _ = std.debug.assert((!expected_is_break));
                    expected_is_break = true;
                }
                if ((actual_is_break != expected_is_break)) {
                    _ = std.log.err("line={d} cp1={x}, cp2={x}: gb1={}, gb2={}, state={}, expected={}, actual={}", .{ line_num, cp1, cp2, gb1, gb2, state, expected_is_break, actual_is_break });
                    success = false;
                }
                if ((parts.peek() == null)) {
                    break;
                }
                cp1 = cp2;
                gb1 = gb2;
                expected_str = next_expected_str;
                cp2 = try parseCp((parts.next()).?);
                gb2 = getpkg.get(.grapheme_break, cp2);
                next_expected_str = (parts.next()).?;
            }
            _ = try std.testing.expect(std.mem.eql(u8, next_expected_str, "÷"));
        }
        _ = try std.testing.expect(success);
}

